ALTER TABLE OPS_RUNTIME_INSTANCE_STATE ADD (desired_runtime_state VARCHAR2(32 CHAR) DEFAULT 'RUNNING' NOT NULL);
ALTER TABLE OPS_RUNTIME_INSTANCE_STATE ADD (actual_runtime_state VARCHAR2(32 CHAR) DEFAULT 'UNKNOWN' NOT NULL);
ALTER TABLE OPS_RUNTIME_INSTANCE_STATE ADD (control_row_version NUMBER(19) DEFAULT 0 NOT NULL);
COMMENT ON COLUMN OPS_RUNTIME_INSTANCE_STATE.desired_runtime_state IS 'Central runtime desired lifecycle state';
COMMENT ON COLUMN OPS_RUNTIME_INSTANCE_STATE.actual_runtime_state IS 'Central runtime actual lifecycle state';
COMMENT ON COLUMN OPS_RUNTIME_INSTANCE_STATE.control_row_version IS 'Central runtime lifecycle optimistic version';
ALTER TABLE BAT_RUNTIME_CAPABILITY DROP CONSTRAINT fk_bat_runtime_capability_instance;
ALTER TABLE BAT_RUNTIME_HEARTBEAT DROP CONSTRAINT fk_bat_runtime_heartbeat_instance;
ALTER TABLE BAT_RUNTIME_CAPABILITY MODIFY (instance_id VARCHAR2(120 CHAR));
ALTER TABLE BAT_RUNTIME_HEARTBEAT MODIFY (instance_id VARCHAR2(120 CHAR));
ALTER TABLE BAT_RUNTIME_CAPABILITY ADD CONSTRAINT fk_bat_runtime_capability_instance FOREIGN KEY (instance_id) REFERENCES OPS_SERVICE_INSTANCE(instance_id) ON DELETE CASCADE;
ALTER TABLE BAT_RUNTIME_HEARTBEAT ADD CONSTRAINT fk_bat_runtime_heartbeat_instance FOREIGN KEY (instance_id) REFERENCES OPS_SERVICE_INSTANCE(instance_id) ON DELETE CASCADE;
